): ?><a class="btn btn-secondary btn-sm" href="<?= pl_e(pl_url('/bank-reconciliation', array_replace($filters, ['id' => (int) $statement['id'], 'row' => (int) $row['id']]))) ?>#match-review">Review matches</a><?php else: ?>Unmatched<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php pl_ui_pagination('/bank-reconciliation', $filters, $statement['page'], $statement['pages']); ?>
