?></select></div><button class="btn btn-primary">Confirm this match</button></form><?php if (count($candidates) > 100): ?><p>Showing 100 candidates on this page. Continue to more candidates to review other possible sources.</p><?php endif; ?><?php endif; ?></section><?php endif; ?>
