        <?php if ($canWrite && $statement['status'] === 'draft'): ?><section class="rounded-panel border border-border bg-surface p-3"><h2 class="section-title mb-2">Complete reconciliation</h2><p>Completion freezes this statement and prevents new entries in this bank account on or before <?= pl_e($statement['end_date']) ?>. Corrections need a later date.</p><form method="post" action="<?= pl_e(pl_url('/bank-reconciliation')) ?>"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><?php pl_ui_return_filters($filters); ?><input type="hidden" name="action" value="complete"><input type="hidden" name="statement_id" value="<?= (int) $statement['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $statement['revision'] ?>"><input type="hidden" name="completion_key" value="bank:<?= (int) $statement['id'] ?>:complete:<?= (int) $statement['revision'] ?>"><label><input type="checkbox" name="review_confirmed" value="1" required> I reviewed every match and the outstanding ledger entries.</label><p><button class="btn btn-primary" <?= !$summary['ready'] ? 'disabled' : '' ?>>Confirm reconciliation</button></p></form></section><?php endif; ?>
