        <form method="post" enctype="multipart/form-data" action="<?= pl_e(pl_url('/bank-reconciliation')) ?>"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><?php pl_ui_return_filters($filters); ?><input type="hidden" name="action" value="preview"><input type="hidden" name="MAX_FILE_SIZE" value="524288"><div class="grid grid-cols-1 md:grid-cols-2 gap-3"><div class="field"><label for="bank-account">Cash / bank account</label><select class="select" id="bank-account" name="account_id" required><option value="">Choose account</option><?php foreach ($accounts as $account): ?><option value="<?= (int) $account['id'] ?>" <?= (int) ($input['account_id'] ?? 0) === (int) $account['id'] ? 'selected' : '' ?>><?= pl_e($account['code'] . ' · ' . $account['name']) ?></option><?php endforeach; ?></select></div><label class="field">Statement reference<input class="input" name="reference" maxlength="120" value="<?= pl_e(pl_web_text($input, 'reference')) ?>" required></label><label class="field">Start date<input class="input" type="date" name="start_date" value="<?= pl_e(pl_web_text($input, 'start_date')) ?>" required></label><label class="field">End date<input class="input" type="date" name="end_date" value="<?= pl_e(pl_web_text($input, 'end_date')) ?>" required></label><label class="field">Opening balance<input class="input" name="opening_balance" inputmode="decimal" value="<?= pl_e(pl_web_text($input, 'opening_balance', '0')) ?>" required></label><label class="field">Closing balance<input class="input" name="closing_balance" inputmode="decimal" value="<?= pl_e(pl_web_text($input, 'closing_balance')) ?>" required></label><label class="field md:col-span-2">Paste CSV<textarea class="textarea" name="csv" rows="7" maxlength="524288" placeholder="date,reference,description,money_in,money_out"><?= pl_e(pl_web_text($input, 'csv')) ?></textarea></label><label class="field md:col-span-2">Or upload CSV<input class="input" type="file" name="statement_csv" accept=".csv,text/csv"></label>